SELECT CASE WHEN customers.credit_limit >= 15700 THEN 'high' WHEN customers.credit_limit >= 3400 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, MAX(web_events.duration_sec) - MIN(web_events.duration_sec) AS duration_sec_range FROM web_events JOIN sessions ON web_events.session_id = sessions.id FULL OUTER JOIN customers ON sessions.customer_id = customers.id WHERE customers.is_active GROUP BY CASE WHEN customers.credit_limit >= 15700 THEN 'high' WHEN customers.credit_limit >= 3400 THEN 'mid' ELSE 'low' END ORDER BY credit_limit_bucket LIMIT 5
